    showPopup(name + ' — ' + g.toFixed(2) + ' eV gap',
      reach
        ? 'The available energy packet is ' + av.toFixed(2) + ' eV, larger than the ' + g.toFixed(2) +
          ' eV gap, so an electron is lifted out of the filled valence band into the empty conduction band. There it is free to move, and the solid conducts.'
        : 'The available energy packet is only ' + av.toFixed(2) + ' eV, smaller than the ' + g.toFixed(2) +
          ' eV gap. There are no allowed electron states inside the gap, so the electron has nowhere to land: it falls back and no current flows.');
  }

  // ── interaction handlers (global) ───────────────────────────────────
  window.update_bandGap = function (v) {
    gapEV = v; activeIdx = idxFor(v); gPromo.clear(); render();
  };
  window.toggle_thermalEnergy = function (on) {
    heated = !!on; gPromo.clear(); render();
  };
  window.trigger_promoteElectron = function () {
    promote(activeIdx >= 0 ? activeIdx : idxFor(gapEV));
  };

  // ── demo player ─────────────────────────────────────────────────────
  var steps = [
    { title: 'One diagram, three materials', promote: false, state: { bandGap: 3, heat: false },
      narration: 'All three panels use the same filled valence band and the same empty conduction band; only the white gap between them changes height. That single distance is the whole classification.' },
    { title: 'Widen the gap: an insulator', promote: false, state: { bandGap: 5.5, heat: false },
      narration: 'Drag the conduction band far above the valence band. With a gap of several electron-volts, the label reads Insulator — electrons have nowhere accessible to go.' },
    { title: 'Try to promote an electron', promote: true, state: { bandGap: 5.5, heat: false },
      narration: 'Click the panel. The promotion arrow rises only as far as the available-energy line and stalls inside the forbidden gap: no electron reaches the conduction band, so no current flows.' },
    { title: 'Shrink to a semiconductor', promote: true, state: { bandGap: 1, heat: false },
      narration: 'Bring the conduction band down to about 1 eV above the valence band. The label switches to Semiconductor: the gap is now comparable to the energy a few electrons can pick up.' },
    { title: 'Heat the semiconductor', promote: true, state: { bandGap: 1, heat: true },
      narration: 'Raise the thermal energy marker. The same 1 eV gap that mostly blocked promotion at room temperature is now crossed — semiconductor conductivity rises with temperature.' },
    { title: 'Close the gap: a conductor', promote: true, state: { bandGap: 0.05, heat: false },
      narration: 'Slide the bands almost together. The white region becomes a sliver, electrons flow into empty conduction states with essentially no energy cost, and the material is a conductor.' }
  ];
  var step = 0, promoTimer = 0;

  function applyStep(k) {
    step = ((k % steps.length) + steps.length) % steps.length;
    var s = steps[step];
    gapEV = s.state.bandGap;
    heated = s.state.heat;
    activeIdx = (step === 0) ? -1 : idxFor(gapEV);

    var si = document.getElementById('bandGapInput');
    if (si) si.value = gapEV;
    var so = document.getElementById('bandGapVal');
    if (so) so.value = gapEV;
    var ti = document.getElementById('thermalEnergyInput');
    if (ti) ti.checked = heated;

    document.getElementById('demoTitle').textContent = s.title;
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (step + 1) + ' / ' + steps.length;

    clearTimeout(promoTimer);
    gPromo.clear();
    render();
    if (s.promote) {
      promoTimer = setTimeout(function () { promote(activeIdx); }, 500);
    } else {
      hidePopup();
    }
  }
  window.nextStep = function () { applyStep(step + 1); };
  window.prevStep = function () { applyStep(step - 1); };

  render();
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: In a solid, the energy separation between the filled valence band and the empty conduction band — the band gap — determines whether electrons can be promoted into mobile states, classifying the material as an insulator, semiconductor, or conductor.
KEY INSIGHT (what students should walk away understanding): Insulators, semiconductors and conductors are not three different diagrams — they are the same diagram with one distance changed: how much energy an electron must gain to leave the filled valence band and reach the empty conduction band.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
