Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:700;font-size:12.5px">Band gaps: one diagram, three materials</span>
<span id="demoTitle" style="font-weight:600;color:#1a4f7a"></span>
<span id="demoNarration" style="display:block;line-height:1.45;color:#333"></span>
<span style="display:flex;gap:8px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-variant-numeric:tabular-nums"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label>Band gap (eV): <output id="bandGapVal">off</output>
  <input id="bandGapInput" type="range" min="0" max="6" step="0.05" value="0"
    oninput="document.getElementById('bandGapVal').value=(+this.value)?(+this.value).toFixed(2):'off';update_bandGap(+this.value)"></label>
<label style="flex-direction:row;align-items:center;gap:6px"><input id="excitationEnergyInput" type="checkbox" onchange="toggle_excitationEnergy(this.checked)"> Excitation energy: High (hot)</label>
<span style="font-size:11px;color:#777;line-height:1.35;margin-top:-2px">Unchecked = Low (cool). The marker is schematic, not a measured value.</span>
<button onclick="trigger_promoteElectron()">⚡ Promote an electron</button>
<span id="liveClass" style="font-size:11.5px;color:#555;line-height:1.4"></span>
<span style="font-size:11px;color:#888;line-height:1.4">Tip: hover or click any band or gap in the figure.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  /* ── canvas: tight viewBox around the three panels ─────────────────── */
  var W = 960, H = 460;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

  var gBase = draw.group();   // blocks + annotations
  var gPromo = draw.group();  // promotion animation
  var gHit = draw.group();    // transparent hover/click zones (always on top)

  /* ── palette / geometry (proportions taken from the source figure) ─── */
  var COL_COND = '#b4cd86', COL_VAL = '#aeb3d6';
  var PW = 205, panelX = [70, 340, 610];
  var valTop = 325, valH = 75, condH = 88, valBottom = valTop + valH;
  var NAMES = ['Insulator', 'Semiconductor', 'Conductor'];
  var canon = [5.5, 1.1, 0.05];
  var MAXPX = 175, KLOG = Math.log(1 + 6 / 0.3);

  /* reserved annotation slots (never shift the baseline layout) */
  var Y_CLASS = 424, Y_RESULT = 449;

  /* ── state ─────────────────────────────────────────────────────────── */
  var gapEV = 0;        // 0 = slider disengaged (textbook view)
  var hot = false;      // excitation energy: low / high
  var revealed = false; // electrons + excitation marker visible
  var activeIdx = -1;

  function gapPx(g) {
    g = Math.max(0, Math.min(6, g));
    return MAXPX * Math.log(1 + g / 0.3) / KLOG;
  }
  function packetEV() { return hot ? 1.6 : 0.6; }
  function gapOf(i) { return (i === activeIdx && gapEV > 0) ? gapEV : canon[i]; }
  function classify(g) { return g < 0.1 ? 'Conductor' : (g < 3 ? 'Semiconductor' : 'Insulator'); }
  function idxFor(g) { return g < 0.1 ? 2 : (g < 3 ? 1 : 0); }
  function classColor(c) { return c === 'Conductor' ? '#1a7f37' : (c === 'Semiconductor' ? '#9a6606' : '#a33028'); }

  function mkText(parent, s, size, o) {
    o = o || {};
    var t = parent.text(s).font({
      family: 'sans-serif', size: size,
      anchor: o.anchor || 'middle',
      weight: o.bold ? 'bold' : 'normal'
    }).fill(o.fill || '#111');
    if (o.halo !== false) {
      t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4.5, 'stroke-linejoin': 'round' });
    }
    return t;
  }

  /* ── main render ───────────────────────────────────────────────────── */
  function render() {
    gBase.clear();
    gHit.clear();
    var shapes = gBase.group();
    var labels = gBase.group();
    var engaged = gapEV > 0;
    var pk = packetEV(), py = valTop - gapPx(pk);

    /* faint energy axis — only once the slider is engaged */
    if (engaged) {
      shapes.line(26, 412, 26, 60).stroke({ color: '#c9c9c9', width: 2 });
      shapes.polygon('26,48 19,64 33,64').fill('#c9c9c9');
      var en = mkText(labels, 'Energy', 17, { fill: '#9b9b9b', halo: false });
      en.center(12, 236); en.rotate(-90);
    }

    for (var i = 0; i < 3; i++) {
      var g = gapOf(i), gp = gapPx(g), x = panelX[i], cx = x + PW / 2;
      var cb = valTop - gp, ct = cb - condH;
      var isActive = engaged && (i === activeIdx);

      if (isActive) {
        var hy = ct - 34, hh = (valBottom + 12) - hy;
        shapes.rect(PW + 26, hh).move(x - 13, hy).fill('#f6a63a').opacity(0.10).radius(8);
        shapes.rect(PW + 26, hh).move(x - 13, hy).fill('none')
          .stroke({ color: '#dd8a26', width: 2, dasharray: '8,5' }).radius(8);
      }

      var cond = shapes.rect(PW, condH).move(x, ct).fill(COL_COND);
      var val = shapes.rect(PW, valH).move(x, valTop).fill(COL_VAL);

      /* dashed guides at the two edges of the white gap */
      if (gp > 14) {
        shapes.line(x, cb, x, valTop).stroke({ color: '#555', width: 1.7, dasharray: '7,5' });
        shapes.line(x + PW, cb, x + PW, valTop).stroke({ color: '#555', width: 1.7, dasharray: '7,5' });
      }

      /* double-headed gap arrow, or free-floating label for a sliver */
      var mid = (valTop + cb) / 2;
      if (gp >= 46) {
        var ax = x + Math.round(PW * 0.27);
        shapes.line(ax, valTop, ax, cb).stroke({ color: '#000', width: 2 });
        shapes.polygon((ax - 6) + ',' + (cb + 13) + ' ' + (ax + 6) + ',' + (cb + 13) + ' ' + ax + ',' + cb).fill('#000');
        shapes.polygon((ax - 6) + ',' + (valTop - 13) + ' ' + (ax + 6) + ',' + (valTop - 13) + ' ' + ax + ',' + valTop).fill('#000');
        if (engaged && gp >= 70) {
          mkText(labels, 'Band gap', 22, { anchor: 'start' }).x(ax + 16).cy(mid - 13);
          mkText(labels, g.toFixed(2) + ' eV', 18, { anchor: 'start', fill: '#444' }).x(ax + 16).cy(mid + 14);
        } else {
          mkText(labels, 'Band gap', 22, { anchor: 'start' }).x(ax + 16).cy(mid);
          if (engaged) mkText(labels, g.toFixed(2) + ' eV', 18, { anchor: 'start', fill: '#444' })
            .x(x + PW + 12).cy(mid);
        }
      } else {
        /* conductor: annotation floats free just outside the block */
        mkText(labels, 'Band gap', 22, { anchor: 'start' }).x(x + PW + 9).cy(mid + 1);
        if (engaged) mkText(labels, g.toFixed(2) + ' eV', 18, { anchor: 'start', fill: '#444' })
          .x(x + PW + 9).cy(mid + 26);
      }

      /* block labels + bold heading */
      mkText(labels, 'Conduction', 22).center(cx, ct + condH / 2);
      mkText(labels, 'Valence', 22).center(cx, valTop + valH / 2);
      mkText(labels, NAMES[i], 23, { bold: true }).center(cx, ct - 22);

      /* electrons sitting at the top of the filled valence band */
      if (revealed) {
        for (var k = 0; k < 6; k++) {
          shapes.circle(8).center(x + 22 + k * 32, valTop + 11).fill('#2b2b40');
        }
      }

      /* live classification caption under the adjustable panel */
      if (isActive) {
        var cls = classify(gapEV);
        mkText(labels, cls, 20, { bold: true, fill: classColor(cls) }).center(cx, Y_CLASS);
      }

      /* hover / click zones */
      (function (idx) {
        function wire(el, tip) {
          el.css('cursor', 'pointer')
            .on('mousemove', function (e) { showTooltip(tip, e); })
            .on('mouseleave', hideTooltip)
            .on('click', function () { promote(idx); });
        }
        var hc = gHit.rect(PW, condH).move(x, ct).fill('#fff').attr('fill-opacity', 0.001);
        var hv = gHit.rect(PW, valH).move(x, valTop).fill('#fff').attr('fill-opacity', 0.001);
        var hg = gHit.rect(PW, Math.max(10, gp)).move(x, cb).fill('#fff').attr('fill-opacity', 0.001);
        wire(hc, 'Conduction band — empty states. An electron here is mobile and carries current. (click to try a promotion)');
        wire(hv, 'Valence band — filled with bound electrons that cannot carry current. (click to try a promotion)');
        wire(hg, 'Forbidden gap — no allowed electron energies lie inside it, so an electron must jump it in one step. (click to try)');
      })(i);
    }

    /* schematic excitation-energy marker */
    if (revealed) {
      var xEnd = panelX[2] + PW + 3;
      shapes.line(36, py, xEnd, py).stroke({ color: '#5a6b8c', width: 1.8, dasharray: '3,6' });
      shapes.line(xEnd, py - 4, xEnd, 54).stroke({ color: '#5a6b8c', width: 1.4, dasharray: '3,5' });
      mkText(labels, 'typical excitation energy (schematic)', 16, { anchor: 'end', fill: '#4d5c7a' })
        .x(946).cy(20);
      mkText(labels, hot ? 'supplied: high (hot)' : 'supplied: low (cool)', 16, { anchor: 'end', fill: '#4d5c7a' })
        .x(946).cy(40);
    }

    var live = document.getElementById('liveClass');
    if (live) {
      live.textContent = (gapEV <= 0)
        ? 'Slider off — the figure as printed: three qualitative gaps, no numbers.'
        : 'Adjusting the ' + NAMES[activeIdx] + ' panel — ' + classify(gapEV) + ' at ' + gapEV.toFixed(2) + ' eV.';
    }
  }

  /* ── promotion attempt ─────────────────────────────────────────────── */
  function promote(i) {
    if (i == null || i < 0) i = 0;
    revealed = true;
    render();
    gPromo.clear();

    var g = gapOf(i), gp = gapPx(g), x = panelX[i], cx = x + PW / 2;
    var cb = valTop - gp, pk = packetEV(), reach = (g <= pk);
    var x0 = x + PW * 0.74;
    var targetY = reach ? (cb - 14) : (valTop - gapPx(pk));
    var col = reach ? '#2e7d32' : '#6b7280';

    var ln = gPromo.line(x0, valTop, x0, valTop).stroke({ color: col, width: 3.2, linecap: 'round' });
    if (!reach) ln.attr('stroke-dasharray', '7,6');
    var dot = gPromo.circle(9.5).center(x0, valTop).fill('#2b2b40');

    ln.animate(650).plot(x0, valTop, x0, targetY).after(function () {
      gPromo.polygon((x0 - 7) + ',' + (targetY + 13) + ' ' + (x0 + 7) + ',' + (targetY + 13) + ' ' + x0 + ',' + targetY)
        .fill(col).opacity(0).animate(180).opacity(1);
      var msg = reach ? 'Electron promoted — current flows' : 'Gap too wide — no conduction';
      var t = gPromo.text(msg).font({ family: 'sans-serif', size: 19, anchor: 'middle', weight: 'bold' }).fill(col);
      t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4.5, 'stroke-linejoin': 'round' });
      t.center(Math.min(Math.max(cx, 175), W - 175), Y_RESULT);
      t.opacity(0).animate(220).opacity(1);
      if (!reach) dot.animate(420).cy(valTop); else dot.fill('#2e7d32');
    });
    dot.animate(650).cy(targetY);

    showPopup(NAMES[i] + ' — ' + (reach ? 'electron promoted' : 'promotion blocked'),
      reach
        ? 'The supplied excitation packet is larger than this gap, so an electron leaves the filled valence band and lands in the empty conduction band. There it is free to move, and the solid conducts.'
        : 'The supplied excitation packet is smaller than this gap. No electron states exist inside the forbidden region, so the electron has nowhere to land: it falls straight back and no current flows.');
  }

  /* ── interaction handlers ──────────────────────────────────────────── */
  window.update_bandGap = function (v) {
    gapEV = v;
    activeIdx = v > 0 ? idxFor(v) : -1;
    if (v > 0) revealed = true;
    gPromo.clear();
    hidePopup();
    render();
    var o = document.getElementById('bandGapVal');
    if (o) o.value = v > 0 ? v.toFixed(2) : 'off';
  };
  window.toggle_excitationEnergy = function (on) {
    hot = !!on; revealed = true; gPromo.clear(); render();
  };
  window.trigger_promoteElectron = function () {
    promote(activeIdx >= 0 ? activeIdx : (hot ? 1 : 0));
  };

  /* ── demo player ───────────────────────────────────────────────────── */
  var steps = [
    { title: 'The figure as printed', state: { gap: 0, hot: false }, promote: -1,
      narration: 'Three materials, one picture: identical filled valence bands and identical empty conduction bands, with only the height of the white forbidden gap changing from left to right. No axis, no numbers — just the qualitative comparison.' },
    { title: 'Try to promote an electron', state: { gap: 0, hot: false }, promote: 0,
      narration: 'Click the insulator panel. Electrons appear at the top of the valence band and one is pushed upward, but the dashed arrow stalls inside the forbidden gap — the supplied-energy marker sits far below the conduction band, so no current flows.' },
    { title: 'Supply more energy', state: { gap: 0, hot: true }, promote: 1,
      narration: 'Switch to the higher excitation energy and click the semiconductor. The marker now rises above its narrower gap and the arrow turns solid green into the conduction band — semiconductors conduct better as they are heated or illuminated.' },
    { title: 'Put a number on the gap', state: { gap: 4, hot: false }, promote: -1,
      narration: 'Engaging the slider adds an energy axis and eV values and turns one panel adjustable. At about 4 eV the conduction band sits far above the valence band and the caption reads Insulator.' },
    { title: 'Shrink toward a semiconductor', state: { gap: 1, hot: false }, promote: -1,
      narration: 'Bring the conduction band down to roughly 1 eV. The label switches to Semiconductor: the gap is now comparable to energies electrons can realistically pick up from heat or light.' },
    { title: 'Close the gap: a conductor', state: { gap: 0.05, hot: false }, promote: 2,
      narration: 'Slide the bands almost together. The white region becomes a sliver, electrons enter empty conduction states at essentially no energy cost, and the material is a conductor.' }
  ];
  var step = 0, promoTimer = 0;

  function applyStep(k) {
    step = ((k % steps.length) + steps.length) % steps.length;
    var s = steps[step];
    gapEV = s.state.gap;
    hot = s.state.hot;
    activeIdx = gapEV > 0 ? idxFor(gapEV) : -1;
    revealed = (step !== 0);

    var si = document.getElementById('bandGapInput');
    if (si) si.value = gapEV;
    var so = document.getElementById('bandGapVal');
    if (so) so.value = gapEV > 0 ? gapEV.toFixed(2) : 'off';
    var ti = document.getElementById('excitationEnergyInput');
    if (ti) ti.checked = hot;

    document.getElementById('demoTitle').textContent = s.title;
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (step + 1) + ' / ' + steps.length;

    clearTimeout(promoTimer);
    gPromo.clear();
    hidePopup();
    render();
    if (s.promote >= 0) {
      promoTimer = setTimeout(function () { promote(s.promote); }, 450);
    }
  }
  window.nextStep = function () { applyStep(step + 1); };
  window.prevStep = function () { applyStep(step - 1); };

  render();
  applyStep(0);
  window.__markRendered();
})();
